# flat probe as data_atlas does it
counts={x:con.execute(f'select count(*) from "{x}"').fetchone()[0] for x in t}
empty={x for x in t if counts[x]==0}
flat=[]
for x in t:
    fk={f[3]:f[2] for f in con.execute(f'PRAGMA foreign_key_list("{x}")') if f[2] in empty}
    for c in con.execute(f'PRAGMA table_info("{x}")'):
        if c[1] in fk and c[3]: flat.append(f"{x}.{c[1]}")
print(); print("flat probe count:",len(flat)); print(sorted(flat))
