python3 - <<'PY'
import sqlite3,json,re
con=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
tabs=[r[0] for r in con.execute("select name from sqlite_master where type='table'")]
hits={}
for t in tabs:
    cols=[c[1] for c in con.execute(f'PRAGMA table_info("{t}")') if (c[2] or '').upper().startswith('TEXT')]
    for c in cols:
        n=0; refs=0
        for (v,) in con.execute(f'select "{c}" from "{t}" where "{c}" is not null'):
            if isinstance(v,str) and v.strip().startswith('['):
                try: arr=json.loads(v)
                except Exception: continue
                if isinstance(arr,list) and arr:
                    n+=1; refs+=sum(1 for x in arr if isinstance(x,str) and re.match(r'^[A-Z]+-\d+',x))
        if n: hits[f"{t}.{c}"]=(n,refs)
for k,v in sorted(hits.items(), key=lambda kv:-kv[1][1]):
    print(f"{k:55s} rows_with_json_array={v[0]:4d} idlike={v[1]}")
print("TOTAL columns:",len(hits))
PY

